//! Typst PDF export inside the helper.
//!
//! The document is Typst source generated by `gv-export`, in which every
//! piece of user text is a string literal. The World it compiles in is in
//! memory: it serves the main file and the generated assets, and denies
//! every other file, every package and the clock. Fonts are the faces of
//! the families the document names, bundled ones first
//! ([`crate::fonts`]), loaded once per process.

use std::collections::{HashMap, HashSet};
use std::path::PathBuf;
use std::sync::{Mutex, OnceLock, PoisonError};

use typst::diag::{FileError, FileResult, PackageError, SourceDiagnostic, Warned};
use typst::foundations::{Bytes, Datetime, Smart};
use typst::syntax::{FileId, RootedPath, Source, VirtualPath, VirtualRoot};
use typst::text::{Font, FontBook};
use typst::utils::LazyHash;
use typst::{Library, LibraryExt, World};
use typst_layout::PagedDocument;
use typst_pdf::PdfOptions;

use crate::protocol::{PdfJob, PdfOutput};

/// Font faces loaded so far, by family (lower case), for the whole process.
struct FontStore {
    /// The bundled faces ([`crate::fonts`]).
    bundled: fontdb::Database,
    /// The families the bundled faces have (lower case): never taken from
    /// the installed fonts.
    bundled_families: HashSet<String>,
    /// The installed fonts, scanned when a document first names a family
    /// the bundled faces lack.
    system: Option<fontdb::Database>,
    /// Families already looked up.
    loaded: HashSet<String>,
    fonts: Vec<Font>,
    /// Files already read (a collection serves several faces).
    files: HashMap<PathBuf, Bytes>,
}

fn store() -> &'static Mutex<FontStore> {
    static STORE: OnceLock<Mutex<FontStore>> = OnceLock::new();
    STORE.get_or_init(|| Mutex::new(FontStore::new(&crate::fonts::search_dirs())))
}

/// The lower-case family names of `db`'s faces.
fn families(db: &fontdb::Database) -> HashSet<String> {
    db.faces()
        .flat_map(|face| face.families.iter().map(|(name, _)| name.to_lowercase()))
        .collect()
}

impl FontStore {
    /// A store with the bundled fonts found in `dirs`.
    fn new(dirs: &[PathBuf]) -> Self {
        let mut bundled = fontdb::Database::new();
        for path in crate::fonts::find_bundled(dirs) {
            if let Err(err) = bundled.load_font_file(&path) {
                eprintln!("glyphvane-helper: cannot load {}: {err}", path.display());
            }
        }
        let bundled_families = families(&bundled);
        Self {
            bundled,
            bundled_families,
            system: None,
            loaded: HashSet::new(),
            fonts: Vec::new(),
            files: HashMap::new(),
        }
    }

    /// Loads the faces of `families` not loaded yet: bundled families from
    /// the bundled files only, the others from the installed fonts.
    fn load(&mut self, families: &[String]) {
        let wanted: Vec<String> = families
            .iter()
            .map(|f| f.to_lowercase())
            .filter(|f| !self.loaded.contains(f))
            .collect();
        if wanted.is_empty() {
            return;
        }
        let (bundled, installed): (Vec<String>, Vec<String>) = wanted
            .iter()
            .cloned()
            .partition(|f| self.bundled_families.contains(f));
        let mut faces = faces_of(&self.bundled, &bundled);
        if !installed.is_empty() {
            let system = self.system.get_or_insert_with(|| {
                let mut db = fontdb::Database::new();
                db.load_system_fonts();
                db
            });
            faces.extend(faces_of(system, &installed));
        }
        for (path, index) in faces {
            let bytes = match self.files.get(&path) {
                Some(bytes) => bytes.clone(),
                None => match std::fs::read(&path) {
                    Ok(data) => {
                        let bytes = Bytes::new(data);
                        self.files.insert(path.clone(), bytes.clone());
                        bytes
                    }
                    Err(_) => continue,
                },
            };
            if let Some(font) = Font::new(bytes, index) {
                self.fonts.push(font);
            }
        }
        self.loaded.extend(wanted);
    }
}

/// The files and indices of `db`'s faces of `families` (lower case).
fn faces_of(db: &fontdb::Database, families: &[String]) -> Vec<(PathBuf, u32)> {
    if families.is_empty() {
        return Vec::new();
    }
    db.faces()
        .filter(|face| {
            face.families
                .iter()
                .any(|(name, _)| families.contains(&name.to_lowercase()))
        })
        .filter_map(|face| match &face.source {
            fontdb::Source::File(path) => Some((path.clone(), face.index)),
            _ => None,
        })
        .collect()
}

/// The families of the bundled fonts this helper found (lower case), for
/// diagnostics and tests.
pub fn bundled_families() -> Vec<String> {
    let store = store().lock().unwrap_or_else(PoisonError::into_inner);
    let mut families: Vec<String> = store.bundled_families.iter().cloned().collect();
    families.sort();
    families
}

fn file_id(path: &str) -> Option<FileId> {
    Some(RootedPath::new(VirtualRoot::Project, VirtualPath::new(path).ok()?).intern())
}

/// The in-memory World of one job.
struct JobWorld {
    library: LazyHash<Library>,
    book: LazyHash<FontBook>,
    fonts: Vec<Font>,
    main: FileId,
    source: Source,
    assets: HashMap<FileId, Bytes>,
}

impl World for JobWorld {
    fn library(&self) -> &LazyHash<Library> {
        &self.library
    }

    fn book(&self) -> &LazyHash<FontBook> {
        &self.book
    }

    fn main(&self) -> FileId {
        self.main
    }

    fn source(&self, id: FileId) -> FileResult<Source> {
        if id == self.main {
            Ok(self.source.clone())
        } else {
            Err(denied(id))
        }
    }

    fn file(&self, id: FileId) -> FileResult<Bytes> {
        match id.root() {
            VirtualRoot::Project => self.assets.get(&id).cloned().ok_or_else(|| denied(id)),
            VirtualRoot::Package(_) => Err(denied(id)),
        }
    }

    fn font(&self, index: usize) -> Option<Font> {
        self.fonts.get(index).cloned()
    }

    fn today(&self, _offset: Option<typst::foundations::Duration>) -> Option<Datetime> {
        None
    }
}

fn denied(id: FileId) -> FileError {
    match id.root() {
        VirtualRoot::Package(spec) => FileError::Package(PackageError::NotFound(spec.clone())),
        VirtualRoot::Project => FileError::AccessDenied,
    }
}

fn messages(diags: &[SourceDiagnostic]) -> Vec<String> {
    diags.iter().map(|d| d.message.to_string()).collect()
}

/// Compiles `job` to PDF.
pub fn pdf(job: &PdfJob) -> Result<PdfOutput, String> {
    let main = file_id("/main.typ").ok_or("bad main path")?;
    let mut assets = HashMap::new();
    for (path, bytes) in &job.assets {
        let id = file_id(path).ok_or_else(|| format!("bad asset path {path}"))?;
        assets.insert(id, Bytes::new(bytes.clone()));
    }
    let fonts = {
        let mut store = store().lock().unwrap_or_else(PoisonError::into_inner);
        store.load(&job.fonts);
        store.fonts.clone()
    };
    let world = JobWorld {
        library: LazyHash::new(Library::builder().build()),
        book: LazyHash::new(FontBook::from_fonts(&fonts)),
        fonts,
        main,
        source: Source::new(main, job.source.clone()),
        assets,
    };
    let Warned { output, warnings } = typst::compile::<PagedDocument>(&world);
    let result = output.map_err(|e| messages(&e).join("; ")).and_then(|doc| {
        let pages = u32::try_from(doc.pages().len()).unwrap_or(u32::MAX);
        if pages > job.max_pages {
            return Err(format!(
                "the document has more than {} pages",
                job.max_pages
            ));
        }
        let options = PdfOptions {
            ident: Smart::Custom(job.ident.clone()),
            creator: Smart::Custom(Some("Glyphvane".to_owned())),
            // No creation date: the same document gives the same bytes.
            timestamp: None,
            ..PdfOptions::default()
        };
        let pdf = typst_pdf::pdf(&doc, &options).map_err(|e| messages(&e).join("; "))?;
        Ok(PdfOutput {
            pdf,
            pages,
            warnings: messages(&warnings),
        })
    });
    // A warm helper otherwise keeps every document's caches.
    typst::comemo::evict(2);
    result
}
